const numbers = [
    10,
    25,
    80,
    150
];

const result = numbers.some((number) => {
    return number > 100;
});

console.log(result);

// true

const numbers = [
    10,
    20,
    30
];

const result = numbers.some((number) => {
    return number > 100;
});

console.log(result);

// false

const numbers = [
    10,
    20,
    30
];

const result = numbers.every((number) => {
    return number > 0;
});

console.log(result);

// true

const numbers = [
    10,
    -5,
    30
];

const result = numbers.every((number) => {
    return number > 0;
});

console.log(result);

// false

const numbers = [
    10,
    20,
    -5
];

console.log(
    numbers.some((number) => number < 0)
);

console.log(
    numbers.every((number) => number > 0)
);

// true
// false
